PYTHONPATH=rag .venv/bin/python - <<'PY'
from pathlib import Path
import hashlib,json,shutil,psycopg
from retrieval.search_chunks import require_database_url
candidate=Path('rag/eval/candidates/answer_evidence_v2');m=json.loads((candidate/'manifest.json').read_text())
for f,sha in m['files'].items():
    assert hashlib.sha256((candidate/f).read_bytes()).hexdigest()==sha,f
    if f.startswith('rag/service/'):assert hashlib.sha256(Path(f).read_bytes()).hexdigest()==sha,f
r=json.loads(Path('rag/eval/reports/langgraph_answer_v2_scope_followup.json').read_text())
u=json.loads(Path('rag/eval/reports/langgraph_answer_v2_scope_followup_unreviewed.json').read_text())
assert [c['response'] for c in r['challenge']]==[c['response'] for c in u['challenge']]
base=Path('rag/eval/baselines/answer_evidence_v2');assert not base.exists();shutil.copytree(candidate,base)
for suffix in ('.json','.md','_unreviewed.json','_unreviewed.md'):
    f='rag/eval/reports/langgraph_answer_v2_scope_followup'+suffix;d=base/f;shutil.copyfile(f,d);m['files'][f]=hashlib.sha256(d.read_bytes()).hexdigest()
m.update(status='human_accepted_frozen',accepted_date='2026-10-13',accepted_baseline=str(base),human_review=r['human_review_summary'],new_answer_human_review='completed_4_of_4_pass')
(base/'manifest.json').write_text(json.dumps(m,ensure_ascii=False,indent=2))
cm=json.loads((candidate/'manifest.json').read_text());cm.update(status='human_accepted_frozen',accepted_baseline=str(base),acceptance_review=r['human_review_summary']);(candidate/'manifest.json').write_text(json.dumps(cm,ensure_ascii=False,indent=2))
print('Frozen answer_evidence_v2: 28 pass / 0 fail, four latest answers only')
with psycopg.connect(require_database_url(),options='-c default_transaction_read_only=on') as c:
    rows=c.execute("SELECT poi_id,name,city,district_name,tags FROM v2.attractions WHERE name IN ('龙门石窟','天子驾六博物馆','洛阳博物馆','隋唐城遗址植物园','从政坊游园','王城公园','隋唐洛阳城应天门遗址') ORDER BY poi_id").fetchall()
    print(json.dumps(rows,ensure_ascii=False))
PY
